{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Gentle, steady clinical support</title>
  <meta name="description" content="Compassionate therapy and an ongoing membership offering to help you build practical coping rhythms in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="/about.html">Start Here</a></li>
          <li><a href="/specialties.html">What I Do</a></li>
          <li><a href="/approach.html">How I Work</a></li>
          <li><a href="/fees.html">Costs & Plans</a></li>
          <li><a href="/faq.html">Common Questions</a></li>
          <li><a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></li>
          <li><a href="/contact.html" class="muted">Connect</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal" id="hero">
      <div class="wrap">
        <div class="hero-content">
          <h1 class="hero-title">Clinical therapy and an ongoing support membership for life transitions</h1>
          <p class="hero-sub">Practical, grounded support that helps you notice what matters, try one small shift at a time, and make changes that stick without pressure.</p>
          <p class="hero-meta">In-person and telehealth in {{CITY}}, {{STATE}} • Confidential clinical care</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Learn how I work</a>
          </div>
        </div>
        <div class="hero-pattern" aria-hidden="true">
          <!-- subtle svg pattern background -->
          <img src="assets/img/pattern.svg" alt="" />
        </div>
      </div>
    </section>

    <!-- Social proof -->
    <section class="social-proof reveal" id="social">
      <div class="wrap">
        <h2>What people notice</h2>
        <div class="testimonials">
          <blockquote>
            "A steady presence and practical steps that felt manageable. I could actually try them between sessions."
            <cite>— client in {{CITY}}</cite>
          </blockquote>
          <blockquote>
            "The ongoing membership helped me check in with habits and keep momentum without feeling judged."
            <cite>— long-term member</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <!-- Benefits / Offer -->
    <section class="benefits reveal" id="benefits">
      <div class="wrap">
        <h2>Support offerings</h2>
        <p class="lede">I offer individual clinical sessions plus a membership pathway designed to keep practice simple and consistent.</p>
        <div class="cards">
          <article class="card">
            <h3>Focused Sessions</h3>
            <p>Structured 50-minute clinical sessions to address immediate concerns, clarify priorities, and develop skills. Appropriate for short-term and longer-term work depending on goals.</p>
            <p class="price">Standard session — <strong>Insurance / self-pay options</strong></p>
          </article>

          <article class="card">
            <h3>Practice Membership</h3>
            <p>A month-to-month membership that centers on maintenance: short check-ins, guided exercises, and weekly practice prompts. Designed for steady support between sessions.</p>
            <p class="price">Membership tiers available — contact to find the fit.</p>
          </article>

          <article class="card">
            <h3>Focused Skill Workshops</h3>
            <p>Small-group workshops that teach practical skills for pacing, boundaries, and managing transition. Not crisis services—educational and skills-focused.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- Process -->
    <section class="process reveal" id="process">
      <div class="wrap">
        <h2>How we typically work together</h2>
        <ol class="process-list">
          <li>
            <strong>Intro conversation</strong>
            <p>A brief phone or video call to make sure we’re a good fit and to clarify current concerns and logistics.</p>
          </li>
          <li>
            <strong>Initial sessions</strong>
            <p>We map immediate priorities, safety, and practical goals so early sessions are useful and focused.</p>
          </li>
          <li>
            <strong>Ongoing care or membership</strong>
            <p>From scheduled sessions to an active membership, we choose a rhythm that supports consistent practice and review progress regularly.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- Session Planner Widget (interactive) -->
    <section class="planner reveal" id="planner">
      <div class="wrap">
        <h2>Session Planner</h2>
        <p class="lede">Build a brief plan to share during your first sessions or to use with your current clinician. This is a planning tool — not a diagnosis.</p>

        <form id="planner-form" class="planner-form" onsubmit="return false;" aria-describedby="planner-desc">
          <div id="planner-desc" class="visually-hidden">Use this planner to create a short summary of concerns, goals, and a suggested meeting rhythm you can copy or download.</div>

          <label>
            Main concern or focus
            <input type="text" id="concern" name="concern" placeholder="e.g., managing work stress, navigating a life change" required>
          </label>

          <label>
            What you hope will be different in 3 months
            <input type="text" id="outcome" name="outcome" placeholder="e.g., calmer mornings; clearer boundaries" required>
          </label>

          <label>
            Meeting rhythm you'd prefer
            <select id="frequency" name="frequency">
              <option value="weekly">Weekly check-ins</option>
              <option value="biweekly">Every two weeks</option>
              <option value="monthly">Monthly with membership check-ins</option>
            </select>
          </label>

          <label>
            Approaches you find helpful
            <input type="text" id="approach" name="approach" placeholder="e.g., CBT skills, mindfulness, values work">
          </label>

          <label>
            Anything else for your clinician to know
            <textarea id="notes" name="notes" rows="3" placeholder="Brief context, logistics, or accommodations"></textarea>
          </label>

          <div class="planner-actions">
            <button id="build-plan" class="btn primary" type="button">Build my plan</button>
            <button id="download-plan" class="btn ghost" type="button">Download .txt</button>
            <button id="copy-plan" class="btn" type="button">Copy summary</button>
          </div>
        </form>

        <div class="planner-output" aria-live="polite">
          <label for="plan-summary">Plan summary (editable)</label>
          <textarea id="plan-summary" readonly rows="8">Your plan will appear here after you click "Build my plan."</textarea>
        </div>
      </div>
    </section>

    <!-- FAQ snippet -->
    <section class="faq-preview reveal" id="faq">
      <div class="wrap">
        <h2>Helpful questions</h2>
        <dl>
          <dt>Is this therapy confidential?</dt>
          <dd>Yes — clinical notes are kept private within legal and ethical limits. See the full policies on the contact page for boundaries and scope.</dd>

          <dt>Do you handle crises?</dt>
          <dd>This practice is not a crisis service. If you are in immediate danger or a medical emergency, please call emergency services or your local crisis line.</dd>
        </dl>
        <p><a href="/faq.html">See more questions</a></p>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta reveal" id="cta">
      <div class="wrap">
        <h2>Ready to begin?</h2>
        <p>If you’d like to explore working together, schedule a brief introductory call to see if we’re a good fit.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">Schedule a call</a>
          <a class="btn ghost" href="/contact.html">Contact — {{PHONE}} • {{EMAIL}}</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • Licensed clinician — {{CITY}}, {{STATE}}</p>
      <nav class="footer-nav">
        <ul>
          <li><a href="/privacy.html">Privacy</a></li>
          <li><a href="/terms.html">Policies</a></li>
          <li><a href="/contact.html">Contact</a></li>
        </ul>
      </nav>
    </div>
  </footer>

  <script>document.getElementById('year').textContent=new Date().getFullYear();</script>
  <script src="assets/js/main.js"></script>
</body>
</html>"} 
