{"path":"assets/css/styles.css","content":"/* Earthy warm theme — single-file styles */
:root{
  --bg:#fbf7f2;
  --muted:#736257;
  --accent:#6a4f3b;
  --accent-2:#caa37a;
  --card:#fff;
  --glass:rgba(255,255,255,0.75);
  --radius:12px;
  --max-width:1100px;
  --shadow:0 6px 20px rgba(102,85,70,0.12);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:#2b2b27;line-height:1.5}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{backdrop-filter:blur(4px);background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.85));border-bottom:1px solid rgba(106,79,59,0.06)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:0.6rem;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:0.45rem 0.6rem;border-radius:8px}
.main-nav a.cta{background:var(--accent);color:#fff;padding:0.5rem 0.9rem}
.main-nav a:hover{background:var(--glass)}
.hero{display:grid;grid-template-columns:1fr 300px;gap:1.5rem;padding:4rem 0}
.hero-title{font-size:clamp(1.5rem,2.8vw,2.6rem);margin:0 0 0.5rem;color:var(--accent)}
.hero-sub{margin:0 0 0.6rem;color:#54463f}
.hero-meta{font-size:0.9rem;color:var(--muted)}
.hero-actions{margin-top:1rem;display:flex;gap:0.6rem}
.btn{border:1px solid rgba(0,0,0,0.06);background:#fff;padding:0.6rem 0.9rem;border-radius:10px;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border-color:transparent}
.btn.ghost{background:transparent;border:1px solid rgba(106,79,59,0.12);color:var(--accent)}
.btn.large{padding:0.9rem 1.2rem}
.hero-pattern img{width:100%;opacity:0.7}
section{margin:2.5rem 0;padding:1.5rem;border-radius:var(--radius);background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.6));box-shadow:var(--shadow)}
.social-proof .testimonials{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
blockquote{margin:0;padding:1rem;border-left:4px solid var(--accent-2);background:rgba(106,79,59,0.03);border-radius:8px}
cite{display:block;margin-top:0.5rem;color:var(--muted);font-size:0.9rem}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.card{padding:1rem;border-radius:10px;background:linear-gradient(180deg,#fff,#fff);border:1px solid rgba(106,79,59,0.04)}
.price{margin-top:0.8rem;color:var(--muted)}
.process-list{display:grid;gap:0.8rem;padding-left:0}
.process-list li{list-style:none;padding:0.8rem;border-radius:8px;background:rgba(106,79,59,0.03)}
.planner-form{display:grid;gap:0.6rem}
.planner-form label{display:block}
.planner-form input,.planner-form textarea,.planner-form select{width:100%;padding:0.6rem;border-radius:8px;border:1px solid rgba(43,43,39,0.08)}
.planner-actions{display:flex;gap:0.5rem;margin-top:0.4rem}
.planner-output textarea{width:100%;padding:0.8rem;border-radius:8px;border:1px solid rgba(43,43,39,0.08);background:#f8f6f4}
.faq-preview dl{display:grid;gap:0.6rem}
.footer-nav ul{display:flex;gap:0.8rem;list-style:none;padding:0;margin:0}
.site-footer{padding:1rem 0;margin-top:2rem}
.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

/* Reveal animations */
.reveal{opacity:0;transform:translateY(12px);transition:opacity 450ms ease,transform 450ms ease}
.reveal.visible{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
}

@media (max-width:800px){
  .hero{grid-template-columns:1fr;}
  .social-proof .testimonials{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Scroll-triggered reveal with reduced motion respect
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const reveals = document.querySelectorAll('.reveal');

  function revealOnScroll(){
    if(prefersReduced){
      reveals.forEach(el=>el.classList.add('visible'));
      return;
    }
    const buffer = window.innerHeight * 0.85;
    reveals.forEach(el=>{
      const r = el.getBoundingClientRect();
      if(r.top < buffer){
        el.classList.add('visible');
      }
    });
  }
  revealOnScroll();
  window.addEventListener('scroll', revealOnScroll, {passive:true});
  window.addEventListener('resize', revealOnScroll);

  // Session Planner widget
  const form = document.getElementById('planner-form');
  if(form){
    const buildBtn = document.getElementById('build-plan');
    const copyBtn = document.getElementById('copy-plan');
    const downloadBtn = document.getElementById('download-plan');
    const summaryArea = document.getElementById('plan-summary');

    function safeVal(id){
      const el = document.getElementById(id);
      return el ? el.value.trim() : '';
    }

    function buildSummary(){
      const concern = safeVal('concern');
      const outcome = safeVal('outcome');
      const freq = safeVal('frequency');
      const approach = safeVal('approach');
      const notes = safeVal('notes');

      const lines = [];
      lines.push('Session Planner — summary');
      lines.push('');
      if(concern) lines.push('Primary focus: ' + concern);
      if(outcome) lines.push('Target in ~3 months: ' + outcome);
      if(freq) lines.push('Preferred rhythm: ' + freq);
      if(approach) lines.push('Helpful approaches: ' + approach);
      if(notes) lines.push('Additional notes: ' + notes);

      lines.push('');
      lines.push('Notes: this is a planning tool and not a substitute for clinical assessment.');

      return lines.join('\n');
    }

    buildBtn.addEventListener('click', ()=>{
      const text = buildSummary();
      summaryArea.value = text;
      summaryArea.focus();
      summaryArea.setSelectionRange(0,0);
    });

    copyBtn.addEventListener('click', async ()=>{
      try{
        const text = summaryArea.value;
        if(!text) return;
        if(navigator.clipboard && navigator.clipboard.writeText){
          await navigator.clipboard.writeText(text);
        } else {
          // fallback
          summaryArea.select();
          document.execCommand('copy');
        }
        copyBtn.textContent = 'Copied';
        setTimeout(()=>copyBtn.textContent='Copy summary',1500);
      }catch(e){
        console.warn('Copy failed',e);
      }
    });

    downloadBtn.addEventListener('click', ()=>{
      const text = summaryArea.value || buildSummary();
      const blob = new Blob([text],{type:'text/plain;charset=utf-8'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'session-plan.txt';
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    });
  }

  // Basic accessible enhancements: external links open appropriately
  document.addEventListener('click', function(e){
    const t = e.target.closest('a');
    if(!t) return;
    const href = t.getAttribute('href') || '';
    if(href.startsWith('http') && !href.includes(location.host)){
      t.setAttribute('rel','noopener noreferrer');
      t.setAttribute('target','_blank');
    }
  });
})();"} 
